// ============================================================
// Prompt Store — current + persistent history (no learning)
// ============================================================

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import type { ComposedPrompt } from '@/types/prompt.types';

interface PromptState {
  current: ComposedPrompt | null;
  history: ComposedPrompt[];
  isGenerating: boolean;

  setCurrent: (p: ComposedPrompt | null) => void;
  setIsGenerating: (v: boolean) => void;
  removeFromHistory: (id: string) => void;
  clearHistory: () => void;
  loadFromHistory: (id: string) => ComposedPrompt | null;
}

export const usePromptStore = create<PromptState>()(
  persist(
    (set, get) => ({
      current: null,
      history: [],
      isGenerating: false,

      setCurrent: (prompt) => {
        set({ current: prompt });
        if (prompt) {
          set((s) => ({
            history: [
              prompt,
              ...s.history.filter((h) => h.id !== prompt.id),
            ].slice(0, 50),
          }));
        }
      },

      setIsGenerating: (isGenerating) => set({ isGenerating }),

      removeFromHistory: (id) =>
        set((s) => ({ history: s.history.filter((h) => h.id !== id) })),

      clearHistory: () => set({ history: [] }),

      loadFromHistory: (id) => {
        const p = get().history.find((h) => h.id === id);
        if (p) {
          set({ current: p });
          return p;
        }
        return null;
      },
    }),
    {
      name: 'prompt-dna-history',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({
        // Don't persist `current` — only history
        history: state.history,
      }),
    },
  ),
);